-- ---------------------------------------------------------------------------
-- Mass update: staff, events and dogs as www.pomdr.org has them.
-- Built 2026-11-13. Live pages read 2026-11-13T11:24. Production rows from the newest
-- backup in db/backups/. Every UPDATE names its row by id AND name; nothing is
-- deleted. One transaction; safe to run twice.
-- ---------------------------------------------------------------------------

START TRANSACTION;

SELECT 'before' AS at, (SELECT COUNT(*) FROM animals WHERE is_available = 1) AS dogs_published, (SELECT COUNT(*) FROM team WHERE status = 'published') AS staff_published, (SELECT COUNT(*) FROM events WHERE status = 'published' AND starts_at >= NOW()) AS upcoming_events;

