INSERT INTO events (title, slug, event_type, description, short_description, starts_at, ends_at, is_all_day, location_name, address_line, city, state, external_url, photo_url, status, is_featured) SELECT 'POMDR in the PG Parade of Lights', 'pg-parade-of-lights-2026', 'Special Event', 'Join POMDR for the Pacific Grove Holiday Parade of Lights! This year''s theme is A Storybook Christmas, with glowing floats, festive fun, and some of POMDR''s adoptable and alumni dogs in teal gear. All friendly dogs are welcome, and storybook or holiday costumes for people and pups are encouraged. Come walk with POMDR and help bring the story to life on Lighthouse Avenue! 6:00 pm, rain or shine.', 'Join POMDR for the Pacific Grove Holiday Parade of Lights! This year''s theme is A Storybook Christmas, with glowing floats, festive fun, and some of POMDR''s adoptable and alumni dogs in teal gear. All friendly dogs are welcome, and storybook or holiday costumes for people and pups are encouraged. Come walk with POMDR and help bring the story to life on Lighthouse Avenue! 6:00 pm, rain or', '2026-12-03 18:00:00', NULL, 0, 'Lighthouse Avenue, Downtown Pacific Grove', 'Lighthouse Avenue', 'Pacific Grove', 'CA', 'https://secure.lglforms.com/form_engine/s/6B3HTLwnmulhREtGATkyQQ', 'https://www.peaceofminddogrescue.org/images/webemails/uploads/Holiday-Parade-of-Lights-2026-599max.jpg', 'published', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM events WHERE slug = 'pg-parade-of-lights-2026' OR (title = 'POMDR in the PG Parade of Lights' AND DATE(starts_at) = '2026-12-03'));
