INSERT INTO events (title, slug, event_type, description, short_description, starts_at, ends_at, is_all_day, location_name, address_line, city, state, external_url, photo_url, status, is_featured) SELECT 'Paws & Presents Holiday Market', 'paws-and-presents-holiday-market-2026', 'Special Event', 'Step into the spirit of the season with this festive afternoon of shopping, sipping, and celebrating in support of Peace of Mind Dog Rescue. Enjoy artisan goods, festive food and drinks and a joyful, dog-loving atmosphere. Sponsored by Robin Venuti, Realtor at Coldwell Bank Realty, and Mechanics Bank', 'Step into the spirit of the season with this festive afternoon of shopping, sipping, and celebrating in support of Peace of Mind Dog Rescue. Enjoy artisan goods, festive food and drinks and a joyful, dog-loving atmosphere. Sponsored by Robin Venuti, Realtor at Coldwell Bank Realty, and Mechanics Bank', '2026-12-06 13:00:00', '2026-12-06 15:30:00', 0, 'The Club at Pasadera', 'The Club at Pasadera', 'Monterey', 'CA', 'https://www.eventbrite.com/e/tpc-monterey-at-pasadera-presents-paws-presents-holiday-market-tickets-1986720022067?aff=oddtdtcreator', 'https://www.peaceofminddogrescue.org/images/webemails/uploads/pawsandpresents.png', 'published', 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM events WHERE slug = 'paws-and-presents-holiday-market-2026' OR (title = 'Paws & Presents Holiday Market' AND DATE(starts_at) = '2026-12-06'));

