-- Parker (adoptable; matched by name, no Shelterluv link)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Parker', name_public), description = 'Looking for a little love, a lot of loyalty, and plenty of tail wags? Parker might just be your guy!

This handsome boy has a heart full of love and a special talent for making his people feel like the center of his world. He bonds quickly and deeply with those he loves, and once you''re in his inner circle, you''ll have a devoted best friend for life.

Parker is a smart cookie and knows his basic commands. He''s ready to show off his good-boy manners at your Thanksgiving gathering!

Parker joined POMDR after his guardian passed away and is now looking for a loving home where he can continue to be someone''s loyal companion.', short_description = 'Looking for a little love, a lot of loyalty, and plenty of tail wags? Parker might just be your guy!', looks_like = 'Maltese/Terrier Mix', sex = 'Male', age_years = 9, weight_lbs = 17, intake_date = COALESCE(intake_date, '2026-11-12'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2345 AND name = 'Parker';
