-- Pumpkin [Foster needed] (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Pumpkin', name_public), description = 'This little cutie is sweeter than a caramel apple and sure to cast a spell on your heart! With a name as cozy as a crisp fall day and a personality that''s pure Halloween magic, Pumpkin is ready to make every day feel like a trip to the pumpkin patch. Whether it''s snuggling up on a chilly autumn evening, going on leaf-crunching adventures, or handing out plenty of tricks and treats (mostly treats!), Pumpkin is sure to bring a little extra magic wherever those paws go. Forget spooky season, it''s snuggle season with Pumpkin!

Pumpkin gets along well with other dogs and would be so pleased to find a home where she can rest with ease. She enjoys gentle walks, lounging around, and keeping her people happy and sound!

Pumpkin joined us from Front Street Animal Shelter in Sacramento after being found as a stray. Due to overcrowding, the shelter reached out to us for help, and we were happy to welcome this sweet girl into our care. Now, Pumpkin is ready for her next chapter and the chance to find a loving forever home!', short_description = 'This little cutie is sweeter than a caramel apple and sure to cast a spell on your heart!', looks_like = 'Chihuahua mix', sex = 'Female', age_years = 7, weight_lbs = 9, intake_date = COALESCE(intake_date, '2026-10-27'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 1, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2338 AND name = 'Pumpkin';
