-- Capri Sun (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Capri Sun', name_public), description = 'Capri Sun is a sweet, easygoing boy who gets along well with other dogs and seems content to just go with the flow. Whether you''re hanging out on the couch or heading out for a stroll, he''s happy to be along for the adventure. We don''t know much about Capri Sun''s past, but we know he''s looking forward to a future filled with love, treats, belly rubs, and a family to call his own.

He''s the kind of pup who doesn''t need much to be happy, just a cozy spot, squeaky toys, and someone to love. He enjoys playing by himself, but also likes cuddles and attention from both dog and human friends. He loves a good walk and has a peppy trot. His back end is a little weak, so he prefers to walk slower, but he doesn''t mind being carried when the time calls for it.

Capri Sun''s ideal day involves lots of playtime with his favorite people nearby, a nice walk, then naps. He would also love to have a few treats sprinkled throughout.

Capri Sun came from Front Street Animal Shelter when it was determined he would be a good fit for the POMDR program.', short_description = 'Capri Sun is a sweet, easygoing boy who gets along well with other dogs and seems content to just go with the flow.', looks_like = 'Maltese mix', sex = 'Male', age_years = 11, weight_lbs = 11, intake_date = COALESCE(intake_date, '2026-07-17'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2184 AND name = 'Capri Sun';
-- Mihla (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Mihla', name_public), description = 'Don''t let her frosted gray coat fool you, this 8 year old is pure sunshine around those she loves. A copilot extraordinaire, this trusty girl loves being a passenger princess (just don''t ask her to back up the trailer.) She''s a wonderful walk companion and trail guide, who takes great joy in pointing out the local flora and fauna to her companions. She took up knitting while waiting for her forever home to find her, after 731+ days at it, her scarf now qualifies for a Guinness book world record but she''s holding out hope!

Miss Mihla enjoys spending her time going for car rides or long walks, playing surgeon with squeaky toys, alerting her fosters about squirrels and birds that dare to cross her path, and attending training regularly to work on building up her leash manners.

This lovely lady would be ideal for a home where she can be the star and not have to share your attention but she may also fit right in with a household that has a mellow dog who doesn''t mind sharing the spotlight. Due to how excited we have seen her get around prey animals we suspect she may not be ideal for a household with cats. We have not seen how she is with children.

The SPCA of Monterey County reached out to us for help because Mihla was becoming increasingly stressed in the shelter environment. She was a favorite among many volunteers who worked with her there, so how could we resist?', short_description = 'Don''t let her frosted gray coat fool you, this 8 year old is pure sunshine around those she loves.', looks_like = 'Labrador Retriever mix', sex = 'Female', age_years = 9, weight_lbs = 60, sponsored_by = 'Judy LeRoy, Tetyana Margolina', intake_date = COALESCE(intake_date, '2024-02-09'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 86 AND name = 'Mihla';
