-- Rita [Foster needed] (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Rita', name_public), description = 'Rita is a gal with a heart full of love and a calm, easygoing charm. She''s the kind of companion who''s happiest in the simple moments: cozy snuggles, gentle strolls, and quietly keeping you company just because she loves being near you. Rita is always ready to settle in close at your feet, beside you on the couch, or wherever her favorite person happens to be. She doesn''t ask for much, just your presence, patience, and a soft spot to land. She''s cat friendly and has done well living with feline housemates.

Rita is gentle and sensitive and prefers not to be picked up or moved abruptly, and with consistency and care, she settles in beautifully. Her twice-daily medication is part of her routine and she does well when it''s thoughtfully tucked into meals.

Rita came to POMDR after her guardian moved into assisted living and could no longer care for her. Now she''s ready for her next chapter,a quiet, loving home where she can share her steady devotion, soft companionship, and endless sweetness.', short_description = 'Rita is a gal with a heart full of love and a calm, easygoing charm.', looks_like = 'Maltese', sex = 'Female', age_years = 13, weight_lbs = 11, intake_date = COALESCE(intake_date, '2025-12-31'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 1, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 1815 AND name = 'Rita';
