INSERT INTO animals (name, name_public, slug, species, shelterluv_id, description, short_description, looks_like, sex, age_years, weight_lbs, sponsored_by, intake_date, photo_url, is_available, is_adopted, adopted_date, is_hospice, is_courtesy, is_foster_needed, is_temp_foster_needed, is_adoption_pending, foster_start_date, foster_end_date, is_draft, is_active, needs_review) SELECT 'Jason', 'Jason', 'jason-2026', 'dog', 'pom-a-20439', 'Jason is a gentle soul who needs a little extra time and a whole lot of understanding to feel safe in the world. He''s a timid boy who is still learning to trust, and he''ll need a patient person who is happy to let him move at his own pace. Jason isn''t ready to hit the walking trails just yet, and he may never be the adventurous, leash-walking type. But with time, kindness, and a little encouragement, he may surprise us! For now, his happy place is somewhere safe and cozy, with the freedom to take each new step when he''s ready.

One of the best things about Jason is how wonderful he is with other dogs! In fact, having a confident canine companion (or even a whole pack!) in his next home is a must for this boy. He takes comfort in his fellow pups and can learn so much by watching them navigate the world. He also does well with kitties, making him a lovely candidate for a home with feline friends, too.

Jason is looking for someone who understands that progress doesn''t always happen overnight. He may need extra time to settle in and build trust, but for the right person, helping him discover that the world can be a safe and happy place will be a very special journey.

