UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Pocus', name_public), description = 'Meet Pocus, a spirited young girl with a whole lot of personality and a little magic up her sleeve! She''s currently recovering from a broken arm, but don''t let that fool you. This youngster hasn''t lost her zest for life one bit. Pocus is proof that a little setback can''t dim a big, happy spirit!

