UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Leaf', name_public), description = 'Leaf is a happy-go-lucky, loving, and affectionate Lady who knows how to keep herself busy. She has an affinity for piles of pillows and fluffy blankets with which she will build a cozy nest for naptime. After resting, she enjoys long, fast-paced walks, extensive yard explorations, sunbathing, and chasing squirrels. She loves being around her people, but also does not mind being home alone for a bit. On car rides, Leaf is well-behaved and quietly sits in the passenger seat. She would be happiest in a home without cats and where she is the only dog. While she tolerates most small, easygoing pups, she really isn''t too fond of bigger dogs who tower over her. Her favorite indoor surfaces to walk on are carpet, rugs, or tile; wood floors not so much.

Leaf is more than ready to meet her forever family! She will be right by your side while you sip a cup of tea and watch the foliage change colors outside your window. She is the most cheerful little companion that anyone could ever ask for. Be-Leaf is her motto!

Lovely Leaf joined POMDR from San Jose Animal Care and Services after she was picked up as a stray.', short_description = 'Leaf is a happy-go-lucky, loving, and affectionate Lady who knows how to keep herself busy. She has an affinity for piles of pillows and fluffy blankets with which she will build a cozy nest for naptime.', looks_like = 'Chihuahua mix', sex = 'Female', age_years = 8, weight_lbs = 15, intake_date = COALESCE(intake_date, '2025-10-22'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 52 AND name = 'Leaf';
-- Sparkler (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Sparkler', name_public), description = 'Sparkler has a way of making everything around her feel a little brighter, just like a warm summer evening filled with laughter, ice cream, and a little bit of magic in the air. This cheerful Lady is easygoing, affectionate, and happy to take life at a mellow pace. She makes it her business to know everything that is going on around the house and the yard, and she will be your faithful shadow throughout the day... unless she is taking one of her frequent beauty naps.

Sparkler gets along well with all people, other dogs, as well as with cats, and she brings a calm, friendly presence wherever she goes. She is quite independent and easily adjusts to new surroundings and circumstances. She loves food and snacks and will perform a happy, twirly dance when she thinks that dinner should be served at any time now. With her fluffy, sparkly coat, darling face, and soft, soulful eyes, she is impossible not to fall in love with. Sparkler currently has monthly appointments with an oncologist to keep a growth in her bladder at bay.

Sweet Sparkler joined us after she was found as a stray and brought to Hitchcock Road Animal Services. They felt she would do best in a senior focused rescue to find her forever family.', short_description = 'Sparkler has a way of making everything around her feel a little brighter, just like a warm summer evening filled with laughter, ice cream, and a little bit of magic in the air.', looks_like = 'Pomeranian mix', sex = 'Female', age_years = 12, weight_lbs = 12, sponsored_by = 'Amanda Nixon in honor of Anna', intake_date = COALESCE(intake_date, '2026-06-22'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2127 AND name = 'Sparkler';
-- Wave (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Wave', name_public), description = 'Meet Wave, a sweet senior lady with a gentle heart and irresistible personality. Though her vision is limited, she navigates the world with quiet confidence and an open heart. She loves soft voices, kind hands, and the comfort of simply being near her people, soaking up affection wherever she finds it.

Wave is an easygoing, affectionate girl who enjoys the simple things in life - cozy naps, gentle pets, and calm companionship. She''s the kind of dog who settles right into your space and makes it feel warmer just by being there. Friendly and loving, she greets new friends with a soft tail wag and a trusting spirit that shines through.

This golden girl is ready for a peaceful forever home where she can be cherished and cared for. Her vision impairment just means she appreciates a steady routine and a little guidance, but what she gives in return is pure devotion. Wave is ready to fill someone''s life with quiet joy, soft moments, and unconditional love.

