-- Bel Air (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Bel Air', name_public), description = 'If a sweet Schnauzer is the dog you''ve been dreaming of, Bel Air (aka "Miss Manners") is here! Social, stylish, and active, Bel Air is your perfect companion for adventures of all kinds, from exploring the outdoors to lounging on the couch! She loves human company, interacts well with other dogs, and flaunts her beautiful silver coat with pride!

Bel Air is just about the most loving and considerate dog out there. Curling up on your lap makes her quite happy. She''ll even jump into the laps of strangers! Bel Air is a cardio queen - she walks two miles at a time and stops to check out wildlife and greet other dogs on the way! Bel Air enjoys exploring the beach, trails, or the neighborhood! She also loves car rides. Her pastimes include playing with toys, munching on treats, and doing happy dances when you get home! Bel Air is house-trained and crate-trained. She knows basic commands but doesn''t enjoy sitting often due to stiff back legs. She is generally quiet and is comfortable with typical household noise.

Bel Air comes to us from Animal Care and Services of San Jose after being found as a stray.', short_description = 'If a sweet Schnauzer is the dog you''ve been dreaming of, Bel Air (aka "Miss Manners") is here!', looks_like = 'Schnauzer', sex = 'Female', age_years = 9, weight_lbs = 21, sponsored_by = 'Marjorie Bullock and Nina Harrison', intake_date = COALESCE(intake_date, '2026-08-05'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2222 AND name = 'Bel Air';
