UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Tuxedo', name_public), description = 'Tuxedo is suited up and ready to dance his way into your heart! This little pup is tiny but mighty. When he''s not snuggled in your arms, he''s hopping around playfully. He''s all ears and is happy to show them off by perking up and looking around.

Tuxedo is a little skinny right now and could use help gaining some weight. He also has a cleft palate, but that sure isn''t slowing him down!

Tuxedo''s ideal day is playing in the sunshine before a serious cuddle session. He''ll be your loyal companion, cuddled right in your arms and observing the world.

Tuxedo joined us from San Jose Animal Care and Services after they determined his medical needs made him a better fit for our program.', short_description = 'Tuxedo is suited up and ready to dance his way into your heart! This little pup is tiny but mighty. When he''s not snuggled in your arms, he''s hopping around playfully.', looks_like = 'Dachshund', sex = 'Male', age_years = 5, weight_lbs = 7, intake_date = COALESCE(intake_date, '2026-09-17'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 1, foster_start_date = NULL, foster_end_date = NULL WHERE id = 98 AND name = 'Tuxedo';
