INSERT INTO animals (name, name_public, slug, species, shelterluv_id, description, short_description, looks_like, sex, age_years, weight_lbs, sponsored_by, intake_date, photo_url, is_available, is_adopted, adopted_date, is_hospice, is_courtesy, is_foster_needed, is_temp_foster_needed, is_adoption_pending, foster_start_date, foster_end_date, is_draft, is_active, needs_review) SELECT 'Dr. Pepper', 'Dr. Pepper', 'dr-pepper-2026-2', 'dog', 'pom-a-20286', 'Meet Dr. Pepper! A cool drink on a hot summer''s day, Dr. Pepper is a calm pup, puttering around the yard or patio. He loves a short stroll about the neighborhood, then returning home to relax. Want to go on a longer walk? He loves riding in a stroller and taking in the scenery.

