-- Snorkel (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Snorkel', name_public), description = 'Snorkel is a true cuddle bug! Snorkel''s bubbly personality will capture your heart in no time. He is a sweet and loving guy who adores people and wants to be loved and pampered in return!

Snorkel is happiest around humans. He loves curling up next to people and snoozing. He even lets his current foster''s niece brush his hair! Snorkel can be a little shy when first meeting new people until he has a chance to sniff them, but he is quick to relax after that. While he is content to nap during the day, Snorkel is no couch potato! He is an active senior who happily goes for walks and rides in the car."Adventure" might as well be his middle name, as Snorkel is not afraid to go out and explore! Treats and belly rubs also top his favorites list. He does not mind cats or other dogs.

Snorkel prefers a home with constant attention, as he gets anxious when left alone. Due to hearing and vision loss, he would thrive with patience and TLC!

Snorkel joined POMDR from the Los Banos Animal Shelter after being found as a stray.', short_description = 'Snorkel is a true cuddle bug! Snorkel''s bubbly personality will capture your heart in no time. He is a sweet and loving guy who adores people and wants to be loved and pampered in return!', looks_like = 'Poodle Terrier mix', sex = 'Male', age_years = 12, weight_lbs = 13, intake_date = COALESCE(intake_date, '2026-06-05'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2102 AND name = 'Snorkel';
-- NEW RECORD: Ashanti (adoptable), Shelterluv pom-a-20412
INSERT INTO animals (name, name_public, slug, species, shelterluv_id, description, short_description, looks_like, sex, age_years, weight_lbs, sponsored_by, intake_date, photo_url, is_available, is_adopted, adopted_date, is_hospice, is_courtesy, is_foster_needed, is_temp_foster_needed, is_adoption_pending, foster_start_date, foster_end_date, is_draft, is_active, needs_review) SELECT 'Ashanti', 'Ashanti', 'ashanti-2026', 'dog', 'pom-a-20412', 'Ashanti came to a local shelter after her elderly guardian suffered a fall and was unable to move for several days. When help finally arrived, they found Ashanti outside, without the care or resources she desperately needed. She was emaciated beyond belief, with painfully overgrown nails curling beneath her feet, swollen legs, severely damaged skin, and large areas of missing fur. On top of everything her body had endured, she was understandably frightened by this strange new world around her.

But beneath all of that neglect is a remarkably sweet girl who seems incredibly grateful for every gentle touch, kind word, and bit of care she receives. She is learning that hands can bring comfort, that meals will keep coming, and that she is finally safe. We can''t wait to watch Ashanti blossom.

We know there is a beautiful dog waiting to emerge as her body heals and her confidence grows, but getting there will take time, patience, and a very special person. Ashanti is looking for an experienced home familiar with German Shepherds and with the patience to let her set the pace. Her adopter will need to be comfortable with the long game: allowing her to decompress, helping her learn what it means to be cared for, and celebrating the tiny victories along the way. She doesn''t need someone looking for an instant best friend. She needs someone willing to earn her trust and walk beside her as she discovers the life she should have had all along.

Ashanti has already survived so much. Now she gets to learn what it feels like to be cherished. We have a feeling that watching this girl come back to life is going to be something pretty special.', 'Ashanti came to a local shelter after her elderly guardian suffered a fall and was unable to move for several days.', 'German Shepherd, Lab mix', 'Female', 9, 55, NULL, '2026-08-29', 'https://www.peaceofminddogrescue.org/images/dogs/Amara082926sm.jpg', 1, 0, NULL, 0, 0, 0, 0, 0, NULL, NULL, 0, 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM animals WHERE slug = 'ashanti-2026' OR shelterluv_id = 'pom-a-20412');
