-- Yankee Candle (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Yankee Candle', name_public), description = 'Meet Yankee Candle! This handsome little gentleman has perfected the finer things in life: leisurely strolls, cozy naps, soft blankets, and keeping a watchful eye on snack time. Yankee is basically a living, breathing four-legged candle: warm, comforting, charming, and guaranteed to make your home feel a little cozier.

His ideal retirement plan includes soft places to nap, a comfy lap or two, gentle strolls, plenty of love, and humans who appreciate the special magic of a senior dog. He gets along great with other dogs and is even a gentleman with kitties. If you''re ready to add a little extra warmth, sweetness, and fluff to your life, Yankee Candle is ready to be your new favorite household fixture. No flame required.

Yankee Candle joined us after the San Jose Animal Care Center reached out to see if we could help him find the kind of peaceful, senior-focused home where he could truly enjoy his golden years. And honestly? We think this fluffy fellow deserves to be spoiled.', short_description = 'Meet Yankee Candle! This handsome little gentleman has perfected the finer things in life: leisurely strolls, cozy naps, soft blankets, and keeping a watchful eye on snack time.', looks_like = 'Pomeranian', sex = 'Male', age_years = 11, weight_lbs = 13, intake_date = COALESCE(intake_date, '2025-09-26'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 59 AND name = 'Yankee Candle';
