UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Watson', name_public), description = 'Lovable little Watson is a tiny senior Chihuahua at his best. He may be getting along in years, but he still has some toddle left in those legs of his. He has a bit of osteoarthritis in his hips, but he doesn''t let that slow him down at all. Aside from taking in the sights and smells around him, Watson loves a good sunbathing session. He''d love to lounge around the yard this summer with you!

Watson is lovely with cats and humans but prefers to be the only pup in the home. In his retirement years, he really just wants all of love for himself (and we understand!)!

Watson joined us from the Sacramento Bradshaw shelter where he landed after being found as a stray. They wanted to help him find a forever family ready to meet the needs of a senior dog, so he joined the POMDR family!', short_description = 'Lovable little Watson is a tiny senior Chihuahua at his best. He may be getting along in years, but he still has some toddle left in those legs of his.', looks_like = 'Chihuahua mix', sex = 'Male', age_years = 13, weight_lbs = 8, intake_date = COALESCE(intake_date, '2025-05-21'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 68 AND name = 'Watson';
-- Bob Barker (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Bob Barker', name_public), description = 'Come on down and meet Bob Barker, who turns everyone into a big lucky winner! With this pup, you will definitely hit the jackpot for good manners, mellow vibes, and lovable charm. Bob is super sweet, very independent, and he gets along with all people, other dogs, as well as cats, mainly by minding his own business. He might benefit from a tender canine companion in the home, but he would also be fine as a solo dog. No drama, no fuss, he just enjoys the simple pleasures of life and being by your side. One of his favorite activities is lying outside in the sun all day in a fluffy, cozy bed.

Bob never demands anything, and that is exactly why he deserves nothing less than to be mollycoddled, fussed over, and doted on from here on out. This guy is well aware that savoring his golden years with a loving forever family is priceless. The time is right to come on down, spin the big wheel, and adopt Bob Barker!

Sweet Bob came to us from Hitchcock Road Animal Services after being found as a stray.', short_description = 'Come on down and meet Bob Barker, who turns everyone into a big lucky winner! With this pup, you will definitely hit the jackpot for good manners, mellow vibes, and lovable charm.', looks_like = 'Terrier', sex = 'Male', age_years = 10, weight_lbs = 12, intake_date = COALESCE(intake_date, '2026-08-28'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2268 AND name = 'Bob Barker';
-- Simba (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Simba', name_public), description = 'Simba is the kind of gentleman who makes an impression without ever asking for much. This sweet senior boy is polite, easygoing, good-natured, and wonderfully independent. He''s happy to spend his days at a leisurely pace, enjoying the company of his people and taking in the world around him. Simba is also a polite pup with other dogs and does well sharing his space with canine friends. He has a calm, unassuming personality and seems perfectly content to simply be part of the family.

Simba was reportedly wandering around town as a stray for several weeks before finally making his way to the shelter. Considering this gentleman is fairly slow-moving and very much enjoys life at his own pace, we''re not quite sure how he managed to become such a seasoned neighborhood explorer! What we do know is that Simba is a really lovely boy who deserves a comfortable place to call home. We think he would do best in a home with other dogs. If you''re looking for a sweet, polite, low-key companion who doesn''t need much fanfare to be happy, Simba might be your guy. He''s ready to leave his wandering days behind and settle into a forever home where he can finally put his paws up and enjoy the good life.

Little Simba joined us from Hitchcock Road Animal Services after he was found as a stray. Due to the shelter''s full status and his senior age, they felt he would do best to join a senior focused rescue to land in his loving forever home.', short_description = 'Simba is the kind of gentleman who makes an impression without ever asking for much. This sweet senior boy is polite, easygoing, good-natured, and wonderfully independent.', looks_like = 'Terrier mix', sex = 'Male', age_years = 10, weight_lbs = 8, intake_date = COALESCE(intake_date, '2026-08-19'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2255 AND name = 'Simba';
-- Timon (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Timon', name_public), description = 'Who loves to play, bask in the sunshine, and give world-class snuggles? Timon! This curious and affectionate little guy likes to be right in the middle of life. He loves people, happily curls up on a welcoming lap, and is always ready for pets, playtime, or a good adventure. He''s a big fan of toys - chasing them, playing fetch, or entertaining himself with a particularly satisfying shake - and his foster says his funny expressions make him even more lovable. At home, he''s a mellow sunbather and champion snuggler, but take him to the beach and he''s ready to go!

Timon is missing a front leg, but you wouldn''t know it from his enthusiasm for walks, outings, and exploring the world. This athletic little tripod has adapted beautifully and hasn''t let it slow him down. He would love a home where he can get plenty of affection, activity, and time with his people. Timon would shine as an only dog or with calm and patient pups in a cat-free home.

Timon came to POMDR after being found as a stray and brought to Hitchcock Road Animal Services. Due to a severe mass on his leg, he was brought to POMDR for emergency treatment. Now, he''s looking for a forever home where he can keep doing what he does best: loving his people and making the most of every day.', short_description = 'Who loves to play, bask in the sunshine, and give world-class snuggles? Timon! This curious and affectionate little guy likes to be right in the middle of life.', looks_like = 'Chihuahua, Dachshund mix', sex = 'Male', age_years = 10, weight_lbs = 12, sponsored_by = 'Frederick Coleman', intake_date = COALESCE(intake_date, '2026-08-19'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2256 AND name = 'Timon';
-- Relish (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Relish', name_public), description = 'Relish is a bright spark of personality with just the right amount of zest to match her name. She has a curious, attentive nature and a sweet little presence that makes her easy to root for from the moment you meet her.

Relish enjoys being near her people, finding cozy spots to tuck into, and taking in the world with quiet interest. She''s the kind of small dog who settles in and quickly becomes part of the rhythm of the home. Relish would prefer a quiet home without too much going on and would benefit from a patient family helping her find her new rhythm after raising three lovely puppies.

After arriving from Front Street Animal Shelter in Sacramento, where she came in as a stray, we discovered that Relish was pregnant! She has now raised her little ones and is ready to find her forever family and be pampered like the princess that she is!', short_description = 'Relish is a bright spark of personality with just the right amount of zest to match her name. She has a curious, attentive nature and a sweet little presence that makes her easy to root for from the moment you meet her.', looks_like = 'Chihuahua mix', sex = 'Female', age_years = 8, weight_lbs = 14, intake_date = COALESCE(intake_date, '2026-06-25'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2133 AND name = 'Relish';
-- Jasper (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Jasper', name_public), description = 'Charming, handsome, and a true gentleman - what more could you want? Jasper checks all those boxes and much more! He is a friendly, well-mannered, and adorable Chihuahua mix who is eager to find his forever home.

Jasper has a heart of gold and loves people! Jasper currently lives with teenagers, and his foster believes he would do well in a home with younger children. Jasper is a fearless and outgoing little guy who loves meeting new people and is friendly towards other dogs!

Although he''s not bouncing off the walls with energy, Jasper does enjoy afternoon walks and does well on a leash. He also loves riding in the car! He enjoys cuddling and unabashedly follows people around seeking attention! He''ll also do best in a home where someone can show him a routine as he settles in!

Jasper came to us from Bradshaw Animal Shelter in Sacramento due to his senior status.', short_description = 'Charming, handsome, and a true gentleman - what more could you want? Jasper checks all those boxes and much more! He is a friendly, well-mannered, and adorable Chihuahua mix who is eager to find his forever home.', looks_like = 'Chihuahua mix', sex = 'Male', age_years = 8, weight_lbs = 13, intake_date = COALESCE(intake_date, '2026-08-14'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2239 AND name = 'Jasper';
