UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Charlie', name_public), description = 'This handsome German Shepherd mix may be blind, but he certainly doesn''t let that slow him down! Charlie is a sweet, loving boy who gets along wonderfully with other dogs and is ready to fill his forever home with companionship, cuddles, and plenty of tail wags. His biggest wish is simple: a loving family who will see what a special boy he truly is.

Charlie is looking for a home without stairs where he can feel safe, comfortable, and confident as he navigates his world. If you have room in your heart for a one-of-a-kind pup who has so much love to give, Charlie could be your perfect match. Give this amazing boy a chance to shine!

Charlie came to us from Hitchcock Road Animal Services after being found as a stray.', short_description = 'This handsome German Shepherd mix may be blind, but he certainly doesn''t let that slow him down!', looks_like = 'German Shepherd mix', sex = 'Male', age_years = 9, weight_lbs = 70, intake_date = COALESCE(intake_date, '2026-08-12'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 0, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 2247 AND name = 'Charlie';
-- Pumba (adoptable; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Pumba', name_public), description = 'Tiny guy, maximum charm: Pumba is a little gentleman with an unforgettable face and a personality that makes a big impression. Sweet, affectionate, and wonderfully endearing, he''s the kind of dog who can brighten a room simply by being in it. Pumba is ready for a home of his own, complete with cozy naps, gentle adventures, and a favorite person to adore.

This little guy is perfectly suited for someone looking for a loyal companion in a very portable package. He''s the kind of dog who''ll tuck in beside you on the couch, tag along for the day, and generally make ordinary life a lot more entertaining simply by being there. And yes, those ears are every bit as magnificent as they look.

