UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Winkle', name_public), description = 'Sweet Winkle came to POMDR from another rescue group when they discovered that his medical needs were more than they could handle. Senior dogs like Winkle with senior-related issues are our specialty so we were happy to bring him into our program. As time has gone by, Winkle developed cataracts and has lost most of his vision. It seems his senior years have caught up to him as well as he has been experiencing some doggie dementia.

