-- Snowflake (hospice; matched by Shelterluv number)
UPDATE animals SET name_public = IF(COALESCE(name_public, '') = '', 'Snowflake', name_public), description = 'Sweet little Snowflake is every bit as unique and dainty as her name suggests. This special senior lady came to Peace of Mind after being picked up as a stray by Hitchcock Road Animal Services in Salinas.

Once in our care, Snowflake was found to have some significant medical needs, including arthritis, multiple heart conditions, and ongoing eye care. Thankfully, this little lady hit the jackpot when she found a loving foster family who welcomed her with open arms and were happy to give her the comfort and care she deserved in her golden years. Given her medical needs, they knew she deserved a place where she could stay comfortable, cherished, and well cared for for the rest of her life. So, along with her beloved guinea pig sibling, Milkshake, Snowflake is officially home for good.

Please consider sponsoring Snowflake''s forever care.', short_description = 'Sweet little Snowflake is every bit as unique and dainty as her name suggests. This special senior lady came to Peace of Mind after being picked up as a stray by Hitchcock Road Animal Services in Salinas.', intake_date = COALESCE(intake_date, '2025-12-10'), is_draft = 0, is_active = 1, needs_review = 0, is_courtesy = 0, is_available = 1, is_adopted = 0, is_hospice = 1, is_foster_needed = 0, is_temp_foster_needed = 0, is_adoption_pending = 0, foster_start_date = NULL, foster_end_date = NULL WHERE id = 35 AND name = 'Snowflake';
-- Zelda (hospice; matched by Shelterluv number)
