INSERT INTO animals (name, name_public, slug, species, shelterluv_id, description, short_description, looks_like, sex, age_years, weight_lbs, sponsored_by, intake_date, photo_url, is_available, is_adopted, adopted_date, is_hospice, is_courtesy, is_foster_needed, is_temp_foster_needed, is_adoption_pending, foster_start_date, foster_end_date, is_draft, is_active, needs_review) SELECT 'Obi', 'Obi', 'obi-2026', 'dog', NULL, 'Sweet Obi is a 7-year-old terrier mix, about 14 lbs. Obi is mostly a homebody. Mellow and quiet, he loves cozying up in blankets all day and enjoys snuggles and cuddles. Once he forms a connection, he becomes very lovey-dovey. Short walks or hikes in quiet areas are his favorite, especially when he gets to sniff everything at his own pace. He doesn''t need much exercise and isn''t a high-energy dog, so working from home with him close by is easy and distraction-free.

Food is a huge motivator for him. He''s the kind of dog who won''t refuse a meal, even when he''s not feeling well. Kongs and rodent-shaped stuffed animals are his favorite toys. He knows all the main commands (sit, jump, come, wait, stay, relax, crate, etc.) and is fully house-trained. Although he has separation anxiety and can be protective of his parents, he''s also been incredibly brave and smart, making real progress in facing his fears. He deserves the chance to keep healing and building confidence.

If you are interested in learning more about Obi, please contact Andrea at 669-240-6425 or by email at [email protected]', 'Sweet Obi is a 7-year-old terrier mix, about 14 lbs. Obi is mostly a homebody. Mellow and quiet, he loves cozying up in blankets all day and enjoys snuggles and cuddles.', NULL, NULL, NULL, NULL, NULL, '2026-02-18', 'https://www.peaceofminddogrescue.org/images/dogs/courtesy/Obi021826.jpg', 1, 0, NULL, 0, 1, 0, 0, 0, NULL, NULL, 0, 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM animals WHERE slug = 'obi-2026');
