INSERT INTO animals (name, name_public, slug, species, shelterluv_id, description, short_description, looks_like, sex, age_years, weight_lbs, sponsored_by, intake_date, photo_url, is_available, is_adopted, adopted_date, is_hospice, is_courtesy, is_foster_needed, is_temp_foster_needed, is_adoption_pending, foster_start_date, foster_end_date, is_draft, is_active, needs_review) SELECT 'Gypsy', 'Gypsy', 'gypsy-2026', 'dog', NULL, 'Gypsy is a Shepherd mix looking for a new home after her guardian sadly passed away. This lovely girl is estimated to be four years old and approximately 50lbs. She is comfortable alone and with dogs. She happened to find her previous guardian by wandering onto their property, and she''s now ready for her next adventure--wandering into your heart! Gypsy is house and crate trained and knows all her basic commands! She is spayed and has all her vaccinations completed.

If you''d like to learn more about Gypsy, reach out to Annette at (408) 921-1534.', 'Gypsy is a Shepherd mix looking for a new home after her guardian sadly passed away. This lovely girl is estimated to be four years old and approximately 50lbs. She is comfortable alone and with dogs.', NULL, NULL, NULL, NULL, NULL, '2026-05-01', 'https://www.peaceofminddogrescue.org/images/dogs/courtesy/Gypsy050126.jpg', 1, 0, NULL, 0, 1, 0, 0, 0, NULL, NULL, 0, 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM animals WHERE slug = 'gypsy-2026');
