-- NEW RECORD: Bailey Bae (courtesy)
INSERT INTO animals (name, name_public, slug, species, shelterluv_id, description, short_description, looks_like, sex, age_years, weight_lbs, sponsored_by, intake_date, photo_url, is_available, is_adopted, adopted_date, is_hospice, is_courtesy, is_foster_needed, is_temp_foster_needed, is_adoption_pending, foster_start_date, foster_end_date, is_draft, is_active, needs_review) SELECT 'Bailey Bae', 'Bailey Bae', 'bailey-bae-2026', 'dog', NULL, 'Bailey is a beautiful, affectionate gal with the most loving big brown eyes, a smile that wins people over instantly, and with her playful energy, most people are shocked to hear she''s 9. She loves daily walks, cuddle time, and being close to her person. She is 30 lbs. and working toward her ideal weight of around 24 lbs., where she''ll truly be feeling her best, and naturally long-haired but groomed every few months.

You can find her on Instagram at @its_baileybae.

She is very smart and familiar with her basic commands, including sit, stay, come, leave it, shake (left and right!), and spin. Bailey loves 2 walks a day, but is happy with one solid outing -- whether that''s a neighborhood walk, a hike (she can comfortably cover several miles), or a trip to the beach (she''s not a water girl, which conveniently keeps her clean!). Bonus points if she spots a lizard to chase or gopher holes to investigate. And don''t let her age fool you -- get her going with a squeaky toy and she plays like a puppy.

Bailey requires a child-free home where she can feel safe, relaxed, and fully herself. She is fearful and reactive around young children, so a home without them is a must. She also truly shines as the only pet -- no competing for attention, just all the love directed at her. She would thrive with someone (or a couple) who can give her plenty of company, whether that''s a retiree, someone who works from home, or a person who can bring her along to work.

If you''d like to learn more about Bailey, please contact Michelle at (408) 250-4422', 'Bailey is a beautiful, affectionate gal with the most loving big brown eyes, a smile that wins people over instantly, and with her playful energy, most people are shocked to hear she''s 9.', NULL, NULL, NULL, NULL, NULL, '2025-11-12', 'https://www.peaceofminddogrescue.org/images/dogs/courtesy/BaileyBae111225.jpg', 1, 0, NULL, 0, 1, 0, 0, 0, NULL, NULL, 0, 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM animals WHERE slug = 'bailey-bae-2026');
