INSERT INTO animals (name, name_public, slug, species, shelterluv_id, description, short_description, looks_like, sex, age_years, weight_lbs, sponsored_by, intake_date, photo_url, is_available, is_adopted, adopted_date, is_hospice, is_courtesy, is_foster_needed, is_temp_foster_needed, is_adoption_pending, foster_start_date, foster_end_date, is_draft, is_active, needs_review) SELECT 'Luna', 'Luna', 'luna-2026', 'dog', NULL, 'Luna a 9-year-old rat terrier ready to seek out her next adventure. She is 19lbs of personality! When meeting new people, she likes to take her time, but soon after, her friendly personality shines through! That being said, she is not very fond of children and would prefer an adult-only household. She also loves to chase cats and would do best without cats.

She is fine with other dogs, though she prefers to have her space and do her own thing--a truly independent lady! And like a true lady, she is house-trained, crate-trained, walks well on leash, and knows her basic commands. Best of all, she has no separation anxiety.

