-- NEW RECORD: Wilson and Walter (courtesy)
INSERT INTO animals (name, name_public, slug, species, shelterluv_id, description, short_description, looks_like, sex, age_years, weight_lbs, sponsored_by, intake_date, photo_url, is_available, is_adopted, adopted_date, is_hospice, is_courtesy, is_foster_needed, is_temp_foster_needed, is_adoption_pending, foster_start_date, foster_end_date, is_draft, is_active, needs_review) SELECT 'Wilson and Walter', 'Wilson and Walter', 'wilson-and-walter-2026', 'dog', NULL, 'What''s better than one pup? Two! Wilson and Walter are a bonded pair of senior boys looking for a home where they can spend their golden years together. Wilson is a 13-year-old Dachshund mix, and Walter is a 11-year-old Yorkie/Jack Russell Terrier mix - between the two of them, they''ve got a whole lot of love and a whole lot of personality. They are crate trained, walk well on leash, and do well with people and other dogs. Wilson is the laid-back one who''s happy to follow your lead, while Walter brings a little extra spunk to the duo. These two have been together their whole lives, and they''re hoping to find someone who will keep it that way.

For more information about Wilson and Walter, please contact Teresa at (831) 706-1576 or Kelly at (828) 337-1765.', 'What''s better than one pup? Two! Wilson and Walter are a bonded pair of senior boys looking for a home where they can spend their golden years together.', NULL, NULL, NULL, NULL, NULL, '2026-08-12', 'https://www.peaceofminddogrescue.org/images/dogs/courtesy/WilsonandWalter081226.jpg', 1, 0, NULL, 0, 1, 0, 0, 0, NULL, NULL, 0, 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM animals WHERE slug = 'wilson-and-walter-2026');
