INSERT INTO animals (name, name_public, slug, species, shelterluv_id, description, short_description, looks_like, sex, age_years, weight_lbs, sponsored_by, intake_date, photo_url, is_available, is_adopted, adopted_date, is_hospice, is_courtesy, is_foster_needed, is_temp_foster_needed, is_adoption_pending, foster_start_date, foster_end_date, is_draft, is_active, needs_review) SELECT 'Appa', 'Appa', 'appa-2026', 'dog', NULL, 'Appa is a friendly, quiet, and smart 90 pound German Shepard, husky mix. He is 5 year old love bug who gets along great with dogs, cats and even bunnies! He is calm and patient with children and understands the "relax" command. He is house trained, crate trained and knows all his basic commands well (sit, stay, down etc.) and walks well on leash. He does well when left alone but would love to accompany you on your weekend hikes, daily runs or coffee dates!

If Appa sounds like the perfect new addition to your family and you would like more information, please contact Ana at [email protected].', 'Appa is a friendly, quiet, and smart 90 pound German Shepard, husky mix. He is 5 year old love bug who gets along great with dogs, cats and even bunnies!', NULL, NULL, NULL, NULL, NULL, '2026-03-21', 'https://www.peaceofminddogrescue.org/images/dogs/courtesy/Appa032126.jpg', 1, 0, NULL, 0, 1, 0, 0, 0, NULL, NULL, 0, 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM animals WHERE slug = 'appa-2026');
